"""Base language handler and Tree-sitter interface for CodeEmbed.

Provides language-agnostic parsing, syntax validation, and comment
filtering powered by Tree-sitter.
"""

from __future__ import annotations

import ast
import logging
import re
from abc import ABC, abstractmethod
from typing import Any

logger = logging.getLogger(__name__)

# Common auto-generation markers across programming languages
_COMMON_AUTO_GEN_MARKERS: list[str] = [
    "auto-generated",
    "autogenerated",
    "automatically generated",
    "generated by",
    "do not edit",
    "do not modify",
    "machine generated",
    "this file is generated",
    "code generated by",
    "@generated",
    "code generated by protobuf",
]


class BaseLanguageHandler(ABC):
    """Abstract base class for programming language handlers."""

    name: str = "base"
    tree_sitter_name: str | None = None
    file_extensions: list[str] = []

    def __init__(self) -> None:
        self._parser: Any = None
        self._parser_initialized: bool = False

    def get_parser(self) -> Any:
        """Lazily load and return the Tree-sitter parser for this language."""
        if not self._parser_initialized:
            self._parser_initialized = True
            if self.tree_sitter_name:
                try:
                    import warnings
                    with warnings.catch_warnings():
                        warnings.simplefilter("ignore")
                        from tree_sitter_languages import get_parser
                        self._parser = get_parser(self.tree_sitter_name)
                except Exception as exc:  # noqa: BLE001
                    logger.debug("Tree-sitter parser unavailable for %s: %s", self.name, exc)
                    self._parser = None
        return self._parser

    def has_valid_syntax(self, code: str) -> bool:
        """Validate code syntax using Tree-sitter (with fallback)."""
        if not code or not code.strip():
            return False

        parser = self.get_parser()
        if parser is not None:
            try:
                tree = parser.parse(bytes(code, "utf-8", errors="replace"))
                return not tree.root_node.has_error
            except Exception:  # noqa: BLE001
                return False

        # Fallback to language-specific heuristic if Tree-sitter is missing
        return self._fallback_syntax_check(code)

    def _fallback_syntax_check(self, code: str) -> bool:
        """Basic fallback check when Tree-sitter is unavailable."""
        return len(code.strip()) > 0

    def is_auto_generated(self, code: str, max_check_lines: int = 10) -> bool:
        """Check if snippet contains auto-generation header comments."""
        lines = code.splitlines()[:max_check_lines]
        header = " ".join(lines).lower()
        return any(marker in header for marker in _COMMON_AUTO_GEN_MARKERS)

    def normalize_whitespace(self, code: str) -> str:
        """Standardize newlines and strip trailing whitespace."""
        code = code.replace("\r\n", "\n").replace("\r", "\n")
        lines = [line.rstrip() for line in code.split("\n")]
        return "\n".join(lines).strip()

    @abstractmethod
    def extract_docstring_and_code(self, item: dict[str, Any]) -> tuple[str, str]:
        """Extract (query/docstring, code_snippet) pair from dataset row."""
        ...
